import math

def is_power_of_p(N, p):
    if N <= 0:
        return False
    if N == 1:
        # Only p^0 = 1. Since p >= 5, this is possible if a=1, b=0 (not allowed) or a=0 (not allowed).
        # For a, b >= 1, p-1 >= 4, so a^(p-1) >= 1 and b >= 1. Thus N >= 2.
        return False

    # Since we are only looking for powers of p, start dividing by p
    while N > 1 and N % p == 0:
        N //= p
    return N == 1

primes_to_check = [5, 7, 11, 13]
solutions = {}

for p in primes_to_check:
    solutions[p] = []
    print(f"--- Searching for p = {p} ---")
    for a in range(1, 11):
        for b in range(a, 31):
            # Calculate A = a^(p-1) + b
            try:
                A = a**(p-1) + b
            except OverflowError:
                # Numbers might get very large for p=13, a=10, b=30. 
                # 10^12 is manageable, 30^12 is around 5*10^17, Python handles this fine.
                # But just in case, we skip if it overflows standard computation limits.
                continue 

            # Calculate B = b^(p-1) + a
            try:
                B = b**(p-1) + a
            except OverflowError:
                continue

            # Check if A and B are powers of p
            is_A_power = is_power_of_p(A, p)
            is_B_power = is_power_of_p(B, p)

            if is_A_power and is_B_power:
                solutions[p].append((a, b))
                print(f"Solution found for p={p}: ({a}, {b})")

# Print results
for p, sol_list in solutions.items():
    if sol_list:
        print(f"Final solutions for p={p}: {sol_list}")
    else:
        print(f"No solutions found for p={p} in the given range.")

def check_solution(p, a, b):
    if a <= 0 or b <= 0 or a > b:
        return False, "Input invalid"

    try:
        val1 = a**(p - 1) + b
        val2 = b**(p - 1) + a
    except OverflowError:
        return False, "Overflow"

    import math

    # Check if val1 and val2 are powers of p
    def is_power_of_p(n, p):
        if n <= 0: return False
        if n == 1: return True # p^0

        # Check divisibility properties
        while n > 1 and n % p == 0:
            n //= p
        return n == 1

    is_pow1 = is_power_of_p(val1, p)
    is_pow2 = is_power_of_p(val2, p)

    if is_pow1 and is_pow2:
        return True, (val1, val2)
    else:
        return False, None

# Test the known solution (p=3, a=2, b=5)
result_known = check_solution(3, 2, 5)
print(f"Check (2, 5) for p=3: {result_known}")

# Test a few candidates identified in the analysis for p=3
candidates = [
    (1, 3), # From x=1, y-x=2 analysis
    (3, 6), # From x=1, y-x=2 analysis
    (9, 10) # From x=2, y-x=1 analysis
]

print("\nTesting candidates for p=3:")
for a, b in candidates:
    result = check_solution(3, a, b)
    print(f"Check ({a}, {b}): {result}")
